"""
MCP Agent — Routes tool calls to external MCP servers.

Provides a unified interface for the engine and LLM to interact with
external MCP servers (mail, calendar, WhatsApp, etc.) without needing
to know their transport or protocol details.

Uses the SafeMCPTransport / MCPTransportManager for resilient communication
with circuit breaker, retry, and graceful fallback.

Registered commands:
  mcp_status     — List all configured servers and their connectivity
  mcp_tools      — List all available tools from connected servers
  mcp_call       — Call a specific tool on a specific server
  mcp_discover   — Re-discover tools from all enabled servers
"""
import json
from typing import Optional

from agents.base_agent import BaseAgent
from log_manager import audit
from transport.mcp_transport import MCPTransportManager


class MCPAgent(BaseAgent):
    """Routes tool calls to registered external MCP servers."""

    def __init__(self):
        super().__init__("mcp-agent")
        self._transport: Optional[MCPTransportManager] = None

    def initialize(self) -> bool:
        try:
            self._transport = MCPTransportManager()
            tools_by_server = self._transport.discover_tools()
            total_tools = sum(len(tools) for tools in tools_by_server.values())
            self.state = "ready"
            self.logger.info(
                "MCP Agent ready — %d servers, %d tools indexed",
                len(tools_by_server), total_tools,
            )
            return True
        except Exception as e:
            self.logger.error("MCP Agent init failed: %s", e)
            return False

    def shutdown(self):
        if self._transport:
            self._transport.shutdown()
        self._transport = None
        super().shutdown()

    # ── tool discovery ─────────────────────────────────────────────────

    def list_connected_servers(self) -> list[dict]:
        if not self._transport:
            return []
        return self._transport.list_servers()

    def list_available_tools(self) -> list[dict]:
        if not self._transport:
            return []
        return self._transport.list_tools()

    def call_tool(self, server_id: str, tool_name: str, arguments: dict = None) -> dict:
        if not self._transport:
            return {"status": "error", "error": "MCP transport not initialized"}
        result = self._transport.call_tool(server_id, tool_name, arguments or {})
        audit(f"MCP_TOOL_CALL server={server_id} tool={tool_name} success={result.success}")
        content_texts = [
            c.get("text", json.dumps(c)) for c in result.content
            if c.get("type") in ("text", "resource")
        ]
        return {
            "status": "success" if result.success else "error",
            "error": result.error,
            "tool": tool_name,
            "server": server_id,
            "content": content_texts,
            "raw": result.content,
        }

    def discover_tools(self) -> dict:
        if not self._transport:
            return {"servers_connected": 0, "tools_total": 0, "tools_by_server": {}}
        tools_by_server = self._transport.discover_tools()
        total_tools = sum(len(tools) for tools in tools_by_server.values())
        return {
            "servers_connected": len(tools_by_server),
            "tools_total": total_tools,
            "tools_by_server": tools_by_server,
        }

    # ── router ─────────────────────────────────────────────────────────

    def process(self, message: dict) -> dict:
        cmd = message.get("payload", {}).get("command", "")
        data = message.get("payload", {}).get("data", {})

        if cmd == "mcp_status":
            return self._ok({
                "servers": self.list_connected_servers(),
                "tools_total": len(self.list_available_tools()),
            })

        if cmd == "mcp_tools":
            tools = self.list_available_tools()
            return self._ok({
                "tools": tools,
                "total": len(tools),
            })

        if cmd == "mcp_call":
            server_id = data.get("server_id")
            tool_name = data.get("tool_name")
            args = data.get("arguments", {})
            if not server_id or not tool_name:
                return self._error("Required: server_id and tool_name")
            return self.call_tool(server_id, tool_name, args)

        if cmd == "mcp_discover":
            result = self.discover_tools()
            return self._ok(result)

        return self._unknown(cmd)

"""
Context Manager Agent.
Loads user profile, recent history, and active needs.
Provides context packet to all other agents.

MCP memory integration:
  - On startup: syncs profile facts to MCP memory (persistent cross-session)
  - get_context: enriches local context with MCP semantic facts
  - add_fact / add_lesson: write directly to MCP memory
"""
import json
import time
from datetime import datetime

from agents.base_agent import BaseAgent
from log_manager import audit
from transport.data_hub import DataHub
from transport.config import AppConfig


class ContextManager(BaseAgent):
    def __init__(self):
        super().__init__("context-manager")
        self._config = AppConfig.instance()
        self._hub = DataHub(self._config)
        self._cache: dict = {}
        self._cache_time: float = 0

    def initialize(self) -> bool:
        try:
            self._load_profile()
            self.state = "ready"
            self.logger.info("Context Manager ready")
            return True
        except Exception as e:
            self.logger.error(f"Init failed: {e}")
            return False

    # ── core ──────────────────────────────────────────────────────────

    def _load_profile(self) -> dict:
        """Load user profile. Prefer DB; fall back to JSON."""
        profile = self._hub.get_user_profile()
        if profile:
            return profile
        if self._config.profile_path.exists():
            with open(self._config.profile_path) as f:
                return json.load(f)
        return {}

    def get_context(self) -> dict:
        """Return full user context. Cached for config.context_ttl_seconds."""
        now = time.monotonic()
        if now - self._cache_time < self._config.context_ttl_seconds and self._cache:
            return self._cache

        profile = self._load_profile()
        habits  = self._hub.get_habits(active_only=True)
        needs   = self._hub.get_needs(active_only=True)
        recent  = self._hub.get_recent_interactions(10)

        self._cache = {
            "profile": profile,
            "habits":  habits,
            "needs":   needs,
            "recent_interactions": recent,
            "mcp_facts": {},
            "generated_at": datetime.now().isoformat(),
        }
        self._cache_time = now
        return self._cache

    def invalidate_cache(self):
        self._cache = {}
        self._cache_time = 0

    # ── router ────────────────────────────────────────────────────────

    def process(self, message: dict) -> dict:
        cmd     = message.get("payload", {}).get("command", "")
        payload = message.get("payload", {})

        if cmd == "get_context":
            return self._ok(self.get_context())

        if cmd == "get_profile":
            return self._ok(self._load_profile())

        if cmd == "invalidate_cache":
            self.invalidate_cache()
            return self._ok({"message": "Cache cleared"})

        if cmd == "add_fact":
            return self._error("MCP memory not available through ContextManager")

        if cmd == "add_lesson":
            return self._error("MCP memory not available through ContextManager")

        if cmd == "list_facts":
            return self._error("MCP memory not available through ContextManager")

        if cmd == "list_lessons":
            return self._error("MCP memory not available through ContextManager")

        if cmd == "mcp_stats":
            return self._error("MCP memory not available through ContextManager")

        if cmd == "sync_profile":
            return self._ok({"message": "Profile data available via DataHub"})

        return self._unknown(cmd)

"""
Engine orchestrator.
Loads all agents, routes messages, runs scheduled jobs.
"""
import uuid
import time
import json
from pathlib import Path
from datetime import datetime

ROOT = Path(__file__).parent

from log_manager import setup_logging, get_logger, audit
from transport.data_hub import DataHub
from transport.event_bus import EventBus
from transport.config import AppConfig

from agents.context_manager   import ContextManager
from agents.task_coordinator  import TaskCoordinator
from agents.insight_generator import InsightGenerator
from agents.reminder_system   import ReminderSystem
from agents.report_generator  import ReportGenerator
from agents.knowledge_indexer import KnowledgeIndexer
from agents.behavior_observer import BehaviorObserver
from agents.pattern_learner import PatternLearner
from agents.mcp_agent import MCPAgent
from agents.github_agent import GitHubAgent


class Engine:
    VERSION = "0.1.0"

    def __init__(self, log_level: str = "INFO"):
        setup_logging(log_level)
        self.logger = get_logger("orchestrator")
        self._config = AppConfig.instance()
        self._hub = DataHub(self._config)
        self._bus = EventBus()
        self._agents: dict = {}
        self._start_time = datetime.now()
        self._interaction_count = 0

    # ── lifecycle ─────────────────────────────────────────────────────────

    def start(self) -> bool:
        self.logger.info(f"Engine v{self.VERSION} starting...")

        # Load agents
        agent_classes = [
            ContextManager,
            TaskCoordinator,
            InsightGenerator,
            ReminderSystem,
            ReportGenerator,
            KnowledgeIndexer,
            MCPAgent,
            GitHubAgent,
        ]

        # Initialize observer (autonomous learning)
        try:
            self._observer = BehaviorObserver()
            self._pattern_learner = PatternLearner()
        except Exception as e:
            self.logger.warning(f"Observer initialization failed: {e}")
            self._observer = None
            self._pattern_learner = None

        for cls in agent_classes:
            agent = cls()
            ok = agent.initialize()
            if self._observer:
                agent.set_observer(self._observer)
            if ok:
                self._agents[agent.id] = agent
                self.logger.info(f"  ✓ Agent: {agent.id}")
            else:
                self.logger.error(f"  ✗ Agent failed to init: {cls.__name__}")

        audit(f"ENGINE_START version={self.VERSION} agents={len(self._agents)}")

        # Phase 3: Auto-sync .md frontmatter with database
        try:
            from sync_scanner import run_scan, summarize
            sync_stats = run_scan()
            self.logger.info("Sync scan: %s", summarize(sync_stats).replace("\n", "; "))
        except Exception as e:
            self.logger.warning("Sync scan failed: %s", e)

        # Phase 4: Initial context snapshot
        try:
            agent_states = {aid: a.state for aid, a in self._agents.items()}
            self._hub.store_context_snapshot(
                session_id=f"session_{self._start_time.strftime('%Y%m%d_%H%M%S')}",
                content={"event": "engine_start", "version": self.VERSION, "agents": agent_states},
                relevance=1.0,
            )
        except Exception as e:
            self.logger.debug("Context snapshot failed: %s", e)

        self.logger.info(f"Engine ready — {len(self._agents)}/{len(agent_classes)} agents active")
        return True

    def stop(self) -> None:
        self.logger.info("Engine stopping...")
        for agent in self._agents.values():
            agent.shutdown()
        audit("ENGINE_STOP")
        self.logger.info("Engine stopped cleanly")

    # ── messaging ─────────────────────────────────────────────────────────

    def send(self, agent_id: str, command: str, data: dict = None, extra: dict = None) -> dict:
        """
        Send a message to an agent.
        Returns the agent's response dict.
        Logs every interaction to memories.db and feeds the behavior observer.
        """
        agent = self._agents.get(agent_id)
        if not agent:
            err = f"Agent not found: {agent_id}"
            self.logger.warning(err)
            return {"status": "error", "error": err}

        message = {
            "id": uuid.uuid4().hex,
            "timestamp": datetime.now().isoformat(),
            "sender": "orchestrator",
            "recipients": [agent_id],
            "action": "request",
            "payload": {"command": command, **(extra or {}), "data": data or {}},
        }

        t0 = time.monotonic()
        try:
            result = agent.handle(message)
            elapsed_ms = int((time.monotonic() - t0) * 1000)
            status = "success" if result.get("status") == "success" else "error"
            error_msg = result.get("error") if status == "error" else None

            self._hub.log_interaction(
                agent_id=agent_id, action=command,
                input_data={"data": data, "extra": extra},
                output_data=result.get("payload"),
                duration_ms=elapsed_ms, status=status,
                error_message=error_msg,
            )

            if self._observer:
                self._observer.observe_cli_command(command)
                if status == "error":
                    self._observer.observe_anomaly_detected(
                        f"agent_{agent_id}_error", "warning"
                    )

            # Fire-and-forget notification to GitHub agent (non-blocking)
            if agent_id != "github-agent" and status == "success":
                self._notify_github_agent(agent_id, command, data)

            # Context snapshot every 5th interaction
            self._interaction_count += 1
            if self._interaction_count % 5 == 0:
                try:
                    self._hub.store_context_snapshot(
                        session_id=f"session_{self._start_time.strftime('%Y%m%d_%H%M%S')}",
                        content={"event": "interaction", "agent": agent_id, "command": command, "status": status},
                        relevance=0.5,
                    )
                except Exception:
                    pass

            return result
        except Exception as e:
            elapsed_ms = int((time.monotonic() - t0) * 1000)
            self._hub.log_interaction(
                agent_id=agent_id, action=command,
                input_data={"data": data, "extra": extra},
                duration_ms=elapsed_ms,
                status="error", error_message=str(e),
            )
            raise

    # ── convenience wrappers ──────────────────────────────────────────────

    def daily_digest(self) -> str:
        r = self.send("report-generator", "daily_digest")
        return r.get("payload", {}).get("report", "Failed to generate digest")

    def weekly_review(self) -> str:
        r = self.send("report-generator", "weekly_review")
        return r.get("payload", {}).get("report", "Failed to generate review")

    def todays_tasks(self) -> list:
        r = self.send("task-coordinator", "get_today")
        return r.get("payload", [])

    def reminders_snapshot(self) -> dict:
        r = self.send("reminder-system", "snapshot")
        return r.get("payload", {})

    def context(self) -> dict:
        r = self.send("context-manager", "get_context")
        return r.get("payload", {})

    def create_task(self, title: str, priority: str = "normal",
                    due_date: str = None, hours: float = None,
                    description: str = "") -> str:
        r = self.send("task-coordinator", "create_task", {
            "title": title,
            "priority": priority,
            "due_date": due_date,
            "estimated_hours": hours,
            "description": description,
        })
        return r.get("payload", {}).get("task_id", "")

    def log_habit(self, habit_name: str, duration_min: int = 0, notes: str = "") -> bool:
        """Find habit by name, log completion, update streak, propagate via DataHub."""
        return self._hub.log_habit_completion(habit_name, duration_min, notes)

    def add_note(self, title: str, content: str = "", tags: str = "", category: str = "general") -> str:
        r = self.send("knowledge-indexer", "add_note", {
            "title": title, content: content, tags: tags, category: category
        })
        return r.get("payload", {}).get("note_id", "")

    def process_natural(self, text: str) -> dict:
        from llm_bridge import IntentClassifier
        classifier = IntentClassifier()
        result = classifier.classify(text)

        if result.intent is None or result.confidence < 0.4:
            return {
                "status": "unknown",
                "text": text,
                "confidence": result.confidence,
                "suggestions": [alt for alt, _ in result.alternatives[:5]],
                "message": "I'm not sure what you mean. Try being more specific.",
            }

        agent = result.intent.agent
        cmd = result.intent.command
        params = result.extracted_params

        if agent == "memory":
            from llm_bridge import check_ollama
            agent_resp = check_ollama()
        elif agent == "learning":
            agent_resp = {"status": "success", "payload": "learning.infer"}
        elif agent == "knowledge-indexer" and cmd == "search":
            query = params.get("query", text)
            agent_resp = self.send(agent, cmd, extra={"query": query})
        elif cmd == "create_task":
            title = params.get("title", text)
            priority = params.get("priority", "normal")
            agent_resp = self.send(agent, cmd, {
                "title": title, "priority": priority,
            })
        elif cmd == "mcp_route":
            from llm_bridge import llm_route_mcp_tool
            tools_resp = self.send("mcp-agent", "mcp_tools")
            tools = tools_resp.get("payload", {}).get("tools", [])
            if not tools:
                agent_resp = {
                    "status": "error",
                    "error": "No MCP tools available — no servers connected or enabled.",
                }
            else:
                route = llm_route_mcp_tool(text, tools)
                if route.success and route.tool_name:
                    agent_resp = self.send(
                        "mcp-agent", "mcp_call", {
                            "server_id": route.server_id,
                            "tool_name": route.tool_name,
                            "arguments": route.arguments,
                        }
                    )
                    if isinstance(agent_resp, dict):
                        agent_resp["_route"] = {
                            "tool": route.tool_name,
                            "server": route.server_id,
                            "args": route.arguments,
                        }
                else:
                    agent_resp = {
                        "status": "error",
                        "error": route.reason or "Could not determine which tool to use.",
                        "_route": {"tool": None, "reason": route.reason},
                    }
        else:
            agent_resp = self.send(agent, cmd)

        return {
            "status": "success",
            "text": text,
            "intent": f"{agent}.{cmd}",
            "intent_label": result.intent.description,
            "confidence": result.confidence,
            "params": params,
            "agent_response": agent_resp,
        }

    def run_sync(self) -> str:
        """Manually trigger frontmatter sync scan."""
        try:
            from sync_scanner import run_scan, summarize
            stats = run_scan()
            return summarize(stats)
